public static async Task<int[]> FetchAllAsync(string[] urls)
{
    using var client = new HttpClient();
    client.Timeout = TimeSpan.FromSeconds(10);

    var tasks = urls.Select(async url =>
    {
        try
        {
            var response = await client.GetAsync(url);
            var content = await response.Content.ReadAsStringAsync();
            return content.Length;
        }
        catch (HttpRequestException)
        {
            return -1;
        }
    });

    int[] results = await Task.WhenAll(tasks);
    return results;
}

public class ManagedBuffer : IDisposable
{
    private byte[]? _buffer;
    private bool _disposed;

    public ManagedBuffer(int size)
    {
        _buffer = new byte[size];
    }

    public Span<byte> GetSpan()
    {
        ObjectDisposedException.ThrowIf(_disposed, this);
        return _buffer.AsSpan();
    }

    public void Dispose()
    {
        if (!_disposed)
        {
            _buffer = null;
            _disposed = true;
        }
        GC.SuppressFinalize(this);
    }
}

public class QueryBuilder
{
    private readonly List<string> _columns = new();
    private string _table = string.Empty;
    private readonly List<string> _conditions = new();
    private string? _orderBy;
    private int? _limit;

    public QueryBuilder Select(params string[] columns)
    {
        _columns.AddRange(columns);
        return this;
    }

    public QueryBuilder From(string table) { _table = table; return this; }
    public QueryBuilder Where(string condition) { _conditions.Add(condition); return this; }
    public QueryBuilder OrderBy(string column) { _orderBy = column; return this; }
    public QueryBuilder Limit(int count) { _limit = count; return this; }

    public string Build()
    {
        var sb = new System.Text.StringBuilder();
        sb.Append($"SELECT {string.Join(", ", _columns)} FROM {_table}");

        if (_conditions.Count > 0)
            sb.Append($" WHERE {string.Join(" AND ", _conditions)}");

        if (_orderBy is not null)
            sb.Append($" ORDER BY {_orderBy}");

        if (_limit.HasValue)
            sb.Append($" LIMIT {_limit.Value}");

        return sb.ToString();
    }
}

using System.Linq.Expressions;

public static class FilterBuilder
{
    public static Func<T, bool> BuildPredicate<T>(
        string propertyName, object value)
    {
        var param = Expression.Parameter(typeof(T), "x");
        var property = Expression.Property(param, propertyName);
        var constant = Expression.Constant(value);
        var converted = Expression.Convert(constant, property.Type);
        var equal = Expression.Equal(property, converted);
        var lambda = Expression.Lambda<Func<T, bool>>(equal, param);
        return lambda.Compile();
    }
}

