using System.Threading.Channels;

public static async Task RunPipelineAsync()
{
    var channel = Channel.CreateBounded<int>(new BoundedChannelOptions(10)
    {
        FullMode = BoundedChannelFullMode.Wait
    });

    var producer = Task.Run(async () =>
    {
        for (int i = 0; i < 50; i++)
        {
            await channel.Writer.WriteAsync(i);
            await Task.Delay(10);
        }
        channel.Writer.Complete();
    });

    var consumer = Task.Run(async () =>
    {
        await foreach (int item in channel.Reader.ReadAllAsync())
        {
            int squared = item * item;
            Console.WriteLine($"{item} => {squared}");
        }
    });

    await Task.WhenAll(producer, consumer);
}

public delegate Task RequestDelegate(HttpContext context);

public class HttpContext
{
    public string Path { get; set; } = "/";
    public int StatusCode { get; set; } = 200;
    public Dictionary<string, string> Headers { get; } = new();
}

public static class Pipeline
{
    public static RequestDelegate Build(
        RequestDelegate handler,
        params Func<RequestDelegate, RequestDelegate>[] middleware)
    {
        RequestDelegate current = handler;

        for (int i = middleware.Length - 1; i >= 0; i--)
        {
            current = middleware[i](current);
        }

        return current;
    }
}

var pipeline = Pipeline.Build(
    ctx => { ctx.StatusCode = 200; return Task.CompletedTask; },
    next => async ctx =>
    {
        ctx.Headers["X-Request-Id"] = Guid.NewGuid().ToString();
        await next(ctx);
    },
    next => async ctx =>
    {
        var sw = System.Diagnostics.Stopwatch.StartNew();
        await next(ctx);
        Console.WriteLine($"{ctx.Path} took {sw.ElapsedMilliseconds}ms");
    }
);

public static class EnumerableExtensions
{
    public static IEnumerable<IReadOnlyList<T>> Batch<T>(
        this IEnumerable<T> source, int size)
    {
        ArgumentOutOfRangeException.ThrowIfLessThan(size, 1);

        var batch = new List<T>(size);

        foreach (T item in source)
        {
            batch.Add(item);
            if (batch.Count == size)
            {
                yield return batch.AsReadOnly();
                batch = new List<T>(size);
            }
        }

        if (batch.Count > 0)
        {
            yield return batch.AsReadOnly();
        }
    }
}

