public abstract record OrderState;
public record Pending(DateTime Created) : OrderState;
public record Confirmed(DateTime Created, string ConfirmationId) : OrderState;
public record Shipped(DateTime Created, string TrackingNumber) : OrderState;
public record Delivered(DateTime Created, DateTime DeliveredAt) : OrderState;
public record Cancelled(DateTime Created, string Reason) : OrderState;

public static class OrderProcessor
{
    public static OrderState Advance(OrderState state, string action) =>
        (state, action) switch
        {
            (Pending p, "confirm") =>
                new Confirmed(p.Created, Guid.NewGuid().ToString("N")[..8]),

            (Confirmed c, "ship") =>
                new Shipped(c.Created, $"TRK-{Random.Shared.Next(100000, 999999)}"),

            (Shipped s, "deliver") =>
                new Delivered(s.Created, DateTime.UtcNow),

            (Pending p, "cancel") =>
                new Cancelled(p.Created, "Customer requested cancellation"),

            (Confirmed c, "cancel") =>
                new Cancelled(c.Created, "Cancelled before shipment"),

            (Cancelled, _) =>
                throw new InvalidOperationException("Cannot advance a cancelled order."),

            (Delivered, _) =>
                throw new InvalidOperationException("Order already delivered."),

            _ => throw new InvalidOperationException(
                $"Invalid transition: {state.GetType().Name} + {action}")
        };

    public static string Describe(OrderState state) => state switch
    {
        Pending { Created: var c } => $"Pending since {c:g}",
        Confirmed { ConfirmationId: var id } => $"Confirmed: {id}",
        Shipped { TrackingNumber: var tn } => $"Shipped: {tn}",
        Delivered { DeliveredAt: var d } => $"Delivered at {d:g}",
        Cancelled { Reason: var r } => $"Cancelled: {r}",
        _ => "Unknown state"
    };
}

public class AsyncPipeline<TIn, TOut>
{
    private readonly Func<TIn, CancellationToken, Task<TOut>> _execute;

    private AsyncPipeline(Func<TIn, CancellationToken, Task<TOut>> execute)
    {
        _execute = execute;
    }

    public static AsyncPipeline<T, T> Create<T>() =>
        new(static (input, _) => Task.FromResult(input));

    public AsyncPipeline<TIn, TNext> Then<TNext>(
        Func<TOut, CancellationToken, Task<TNext>> transform)
    {
        var previous = _execute;
        return new AsyncPipeline<TIn, TNext>(async (input, ct) =>
        {
            ct.ThrowIfCancellationRequested();
            TOut intermediate = await previous(input, ct);
            return await transform(intermediate, ct);
        });
    }

    public AsyncPipeline<TIn, TOut> WithTimeout(TimeSpan timeout)
    {
        var inner = _execute;
        return new AsyncPipeline<TIn, TOut>(async (input, ct) =>
        {
            using var cts = CancellationTokenSource.CreateLinkedTokenSource(ct);
            cts.CancelAfter(timeout);
            return await inner(input, cts.Token);
        });
    }

    public Task<TOut> ExecuteAsync(TIn input, CancellationToken ct = default)
        => _execute(input, ct);
}

var pipeline = AsyncPipeline<string, string>.Create<string>()
