public abstract record Expr;
public record Num(double Value) : Expr;
public record Var(string Name) : Expr;
public record BinOp(Expr Left, char Op, Expr Right) : Expr;
public record UnaryOp(char Op, Expr Operand) : Expr;
public record LetIn(string Name, Expr Value, Expr Body) : Expr;

public static class Evaluator
{
    public static double Eval(
        Expr expr,
        IReadOnlyDictionary<string, double> env) => expr switch
    {
        Num { Value: var v } => v,

        Var { Name: var n } => env.TryGetValue(n, out double val)
            ? val
            : throw new KeyNotFoundException($"Undefined variable: {n}"),

        BinOp { Left: var l, Op: var op, Right: var r } => op switch
        {
            '+' => Eval(l, env) + Eval(r, env),
            '-' => Eval(l, env) - Eval(r, env),
            '*' => Eval(l, env) * Eval(r, env),
            '/' => Eval(r, env) is 0.0
                ? throw new DivideByZeroException()
                : Eval(l, env) / Eval(r, env),
            _ => throw new NotSupportedException($"Unknown operator: {op}")
        },

        UnaryOp { Op: '-', Operand: var o } => -Eval(o, env),

        LetIn { Name: var name, Value: var value, Body: var body } =>
            Eval(body, new Dictionary<string, double>(env)
            {
                [name] = Eval(value, env)
            }),

        _ => throw new NotSupportedException($"Unknown expression: {expr}")
    };
}

// let x = 3 in (x + 2) * -x
var program = new LetIn("x", new Num(3),
    new BinOp(
        new BinOp(new Var("x"), '+', new Num(2)),
        '*',
        new UnaryOp('-', new Var("x"))));

var result = Evaluator.Eval(program, new Dictionary<string, double>());
Console.WriteLine($"Result: {result}");
